import {
  IconCheck, IconX, IconPencil, IconBan, IconRefresh, IconArrowBackUp, IconExchange,
} from '@tabler/icons-angular';
import type { HrmStatusTone } from '../table-cells/hrm-status-cell';
import type { HrmButtonVariant } from '../general/hrm-button';

/** Tông MÀU nút hành động — bám ý nghĩa: đồng ý=primary(xanh) · từ chối/hủy=error(đỏ)
 *  · cảnh báo/hủy tạm=warning(vàng) · yêu cầu thay đổi=violet(tím) · trung tính=neutral. */
export type HrmActionTone = 'primary' | 'error' | 'warning' | 'violet' | 'neutral';

/** Trạng thái CHỦ ĐẠO của hệ thống — bám State Machine "Trạng thái chung hệ thống".
 *  Bắt đầu/Kết thúc là node khởi tạo/kết thúc (không phải trạng thái lưu trữ) nên không nằm ở đây. */
export type HrmWorkflowStatus =
  | 'pending'          // Chờ duyệt
  | 'approved'         // Đã duyệt
  | 'rejected'         // Đã từ chối
  | 'pendingCancel'    // Chờ hủy
  | 'cancelled'        // Đã hủy
  | 'changeRequested'; // Yêu cầu thay đổi

/** Meta 1 trạng thái: tông màu (semantic token) + nhãn song ngữ. */
export interface HrmWorkflowStatusMeta {
  tone: HrmStatusTone;
  vi: string;
  en: string;
}

/** Bảng tra trạng thái chuẩn → tông + nhãn. Dùng làm mặc định toàn hệ thống.
 *  Tông theo ý nghĩa: chờ = warning · đạt = success · loại = error · thay đổi = violet. */
export const HRM_WORKFLOW_STATUS: Record<HrmWorkflowStatus, HrmWorkflowStatusMeta> = {
  pending:         { tone: 'warning', vi: 'Chờ duyệt',        en: 'Pending approval' },
  approved:        { tone: 'success', vi: 'Đã duyệt',         en: 'Approved' },
  rejected:        { tone: 'error',   vi: 'Đã từ chối',       en: 'Rejected' },
  pendingCancel:   { tone: 'warning', vi: 'Chờ hủy',          en: 'Pending cancellation' },
  cancelled:       { tone: 'error',   vi: 'Đã hủy',           en: 'Cancelled' },
  changeRequested: { tone: 'violet',  vi: 'Yêu cầu thay đổi', en: 'Change requested' },
};

/** 1 hành động (nút) trên 1 trạng thái = 1 chuyển tiếp của State Machine. */
export interface HrmWorkflowAction {
  /** key hành động (phát ra khi bấm). */
  key: string;
  vi: string;
  en: string;
  /** Trạng thái đích sau khi thực hiện (tài liệu hoá luồng — không tự chuyển). */
  to: HrmWorkflowStatus | 'end';
  variant: HrmButtonVariant;
  danger?: boolean;
  /** Tông màu nút (semantic) — quyết định màu nền/chữ. */
  tone: HrmActionTone;
  /** Icon Tabler đứng trước nhãn (nút dạng icon + text). */
  icon: unknown;
}

/** Bảng tra hành động theo trạng thái — bám đúng các mũi tên State Machine.
 *  Trạng thái kết thúc (Đã hủy) không có hành động (→ Kết thúc). */
export const HRM_WORKFLOW_ACTIONS: Record<HrmWorkflowStatus, HrmWorkflowAction[]> = {
  // Chờ duyệt → Duyệt(xanh) | Từ chối(đỏ) | Yêu cầu thay đổi(tím)
  pending: [
    { key: 'approve',       vi: 'Duyệt',            en: 'Approve',        to: 'approved',        variant: 'primary', tone: 'primary', icon: IconCheck },
    { key: 'reject',        vi: 'Từ chối',          en: 'Reject',         to: 'rejected',        variant: 'primary', tone: 'error',   danger: true, icon: IconX },
    { key: 'requestChange', vi: 'Yêu cầu thay đổi', en: 'Request change', to: 'changeRequested', variant: 'primary', tone: 'violet',  icon: IconExchange },
  ],
  // Đã duyệt → Yêu cầu hủy(vàng) | Hủy(đỏ)
  approved: [
    { key: 'requestCancel', vi: 'Yêu cầu hủy', en: 'Request cancel', to: 'pendingCancel', variant: 'primary', tone: 'warning', icon: IconBan },
    { key: 'cancel',        vi: 'Hủy',         en: 'Cancel',         to: 'cancelled',     variant: 'primary', tone: 'error', danger: true, icon: IconX },
  ],
  // Đã từ chối → Đăng ký lại (→ Chờ duyệt)
  rejected: [
    { key: 'resubmit', vi: 'Đăng ký lại', en: 'Resubmit', to: 'pending', variant: 'primary', tone: 'primary', icon: IconRefresh },
  ],
  // Chờ hủy → Duyệt hủy(đỏ) | Bỏ yêu cầu hủy(trung tính)
  pendingCancel: [
    { key: 'approveCancel', vi: 'Duyệt hủy',      en: 'Approve cancel', to: 'cancelled', variant: 'primary', tone: 'error', danger: true, icon: IconCheck },
    { key: 'dismissCancel', vi: 'Bỏ yêu cầu hủy', en: 'Dismiss cancel', to: 'approved',  variant: 'default', tone: 'neutral', icon: IconArrowBackUp },
  ],
  // Đã hủy → (kết thúc) — không hành động
  cancelled: [],
  // Yêu cầu thay đổi → Chỉnh sửa(xanh) | Rút đơn(đỏ)
  changeRequested: [
    { key: 'edit',     vi: 'Chỉnh sửa', en: 'Edit',     to: 'pending',   variant: 'primary', tone: 'primary', icon: IconPencil },
    { key: 'withdraw', vi: 'Rút đơn',   en: 'Withdraw', to: 'cancelled', variant: 'primary', tone: 'error', danger: true, icon: IconArrowBackUp },
  ],
};
